import React, { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import {
  Box, Typography, Paper, Tabs, Tab, Button, CircularProgress,
  Chip, Avatar, Divider
} from '@mui/material';
import ArrowBackIcon from '@mui/icons-material/ArrowBack';
import EditIcon from '@mui/icons-material/Edit';
import PersonIcon from '@mui/icons-material/Person';
import WorkIcon from '@mui/icons-material/Work';
import DescriptionIcon from '@mui/icons-material/Description';
import { useEmployee } from '../core/hooks/useEmployees';
import StatusBadge from '../core/components/ui/StatusBadge';
import BasicInfoTab from '../core/components/employee/BasicInfoTab';
import EmploymentTab from '../core/components/employee/EmploymentTab';
import DocumentsTab from '../core/components/employee/DocumentsTab';

const EmployeeProfilePage = () => {
  const { t } = useTranslation();
  const { id } = useParams();
  const navigate = useNavigate();
  const { data: employee, isLoading, error } = useEmployee(id);
  const [tabIndex, setTabIndex] = useState(0);

  if (isLoading) return <Box sx={{ textAlign: 'center', p: 6 }}><CircularProgress /></Box>;
  if (error || !employee) return (
    <Box sx={{ textAlign: 'center', p: 4 }}><Typography color="error">{t('employees.not_found')}</Typography>
      <Button onClick={() => navigate('/employees')} sx={{ mt: 2 }}>{t('common.back')}</Button>
    </Box>
  );

  return (
    <Box>
      {/* Back + Edit */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 2 }}>
        <Button startIcon={<ArrowBackIcon />} onClick={() => navigate('/employees')}>{t('common.back')}</Button>
        <Button variant="outlined" startIcon={<EditIcon />} onClick={() => navigate(`/employees/${id}/edit`)}>{t('common.edit')}</Button>
      </Box>

      {/* Employee Summary Card */}
      <Paper sx={{ p: 3, mb: 3, background: 'linear-gradient(135deg, rgba(25,118,210,0.08) 0%, rgba(66,165,245,0.04) 100%)' }}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 3, flexWrap: 'wrap' }}>
          <Avatar sx={{ width: 72, height: 72, bgcolor: 'primary.main', fontSize: 28 }}>
            {employee.first_name?.charAt(0)}{employee.last_name?.charAt(0)}
          </Avatar>
          <Box sx={{ flex: 1 }}>
            <Typography variant="h5" fontWeight="bold">{employee.full_name}</Typography>
            <Box sx={{ display: 'flex', gap: 1, mt: 1, flexWrap: 'wrap' }}>
              <Chip label={`${t('employees.employee_id')}: ${employee.employee_id}`} size="small" />
              <Chip label={employee.department_detail?.name || '—'} size="small" color="primary" variant="outlined" />
              <Chip label={employee.job_title_detail?.name || '—'} size="small" color="secondary" variant="outlined" />
              <StatusBadge status={employee.status} />
            </Box>
          </Box>
        </Box>
      </Paper>

      {/* Tabs */}
      <Paper sx={{ mb: 3 }}>
        <Tabs
          value={tabIndex}
          onChange={(e, v) => setTabIndex(v)}
          variant="scrollable"
          scrollButtons="auto"
          sx={{ borderBottom: 1, borderColor: 'divider', px: 2 }}
        >
          <Tab icon={<PersonIcon />} label={t('employees.basic_info')} iconPosition="start" />
          <Tab icon={<WorkIcon />} label={t('employees.employment_info')} iconPosition="start" />
          <Tab icon={<DescriptionIcon />} label={t('documents.title')} iconPosition="start" />
        </Tabs>

        <Box sx={{ p: 3 }}>
          {tabIndex === 0 && <BasicInfoTab employee={employee} />}
          {tabIndex === 1 && <EmploymentTab employee={employee} />}
          {tabIndex === 2 && <DocumentsTab employeeId={employee.id} />}
        </Box>
      </Paper>
    </Box>
  );
};

export default EmployeeProfilePage;
